def get_palindrome_range(n):
    # Initialize count for each type of palindrome
    count = [n, n+1]

    # Check if there are any more than 10 of each type
    if len(count) > 2) and (len(count) + 1) < 3:
        return count[0] + 1
    else:
        return count[0]

# Test the function
print(get_palindrome_range(11)))
